    undoBook: function () {
        var selection = this.getUsufructsGrid().getSelectionModel().getSelected();
        var activity = selection.data.activity;
        var acquisition_period = this.getAcquisitionPeriodGrid().getSelectionModel().getSelected().data.pk;

        if (selection.lenght === 0 || selection.lenght > 1) {
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Selecione um usufruto.'
            });
        }
        else {
            var message = '';
            this.getUsufructsGrid().getStore().data.items.map(function (item) {
                if (activity == item.data.activity)
                    message += '<br>' + item.data.unicode;
            });
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: 'Atenção!<br>Esta ação desmarca todas marcações realizadas juntas.<br>Você deseja desmarcá-la(s)?<br>' + message,
                scope: this,

                fn: function (btn) {
                    if (btn == 'no') return;
                    var params = {
                        actionCustom: 'cancel',
                        acquisition_period: acquisition_period,
                        activity: activity
                    };
                    this._undoBook(params);
                }
            });
        }
    },

    _cancel: function (params) {
        var rest = Ext._create('rh.dayoff.mpmt.activity.Restful', { resource: 'DAYOFFAcquisitionPeriodMPMT' });
        var mask = Ext._create('Ext.LoadMask', this.getEl(), { msg: 'Processando informações.' });
        var wnd = this;

        mask.show();
        rest._process(
            params,
            {
                scope: this,
                fn: function (rst) {
                    core.invokeCallback((wnd.externalCallback || { fn: Ext.emptyFn }), rst.message);
                }
            },
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: 'Informando',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message
                    });
                }
            },
            {
                fn: function () {
                    mask.hide();
                }
            }
        );
    },

