    getSecondGrid: function (cfgManage, cfg) {
        if (!this._secondGrid)
            this._secondGrid = Ext._create('Ext.TabPanel', {
                region: 'south',
                height: 300,
                activeTab: 0,
                items: [
                    this.getUsufructsPanel(),
                    this.getAcitivityPanel(cfgManage, {})
                ]
            });

        return this._secondGrid
    },

    observerAcquisitionPeriod: function (value, prevent) {
        prevent = core.nullValue(prevent, false);

        if (value !== undefined) {
            this._pas = value;

            !prevent && this.observeAPSelected();
        }

        return this._pas;
    },

    observeAPSelected: function () {
        var value = this.observerAcquisitionPeriod();

        if (value) {
            this.getUsufructsGrid().setParam('activity__acquisition_period', value);
            this.getUsufructsGrid().setFilterProperty('activity__acquisition_period', value, 1);
            this.getUsufructsGrid().enable();

            this.getActivityGrid().setParam('acquisition_period', value);
            this.getActivityGrid().setFilterProperty('acquisition_period', value, 2, false);
            this.getActivityGrid().enable();
        }
        else if (this.getUsufructsGrid().getParams().activity__acquisition_period !== undefined) {
            this.getUsufructsGrid().setParam('activity__acquisition_period', 0);
            this.getUsufructsGrid().setFilterProperty('activity__acquisition_period', 0, 1, false);
            this.getUsufructsGrid().getStore().removeAll();
            this.getUsufructsGrid().disable();

            this.getActivityGrid().setParam('acquisition_period', 0);
            this.getActivityGrid().setFilterProperty('acquisition_period', 0, 2,false);
            this.getActivityGrid().getStore().removeAll();
            this.getActivityGrid().disable();
        }
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});
        var _manage = this;

        Ext.applyIf(
            cfg,
            {
                title: 'Período Aquisitivo',
                externalCallback: {
                    fn: function () {
                        _manage.getAcquisitionPeriodGrid(cfg, {}).getStore().reload();
                    }
                },
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getAcquisitionPeriodGrid(cfg, {}),
                    this.getSecondGrid(cfg, {}),
                ],
            }
        );

        rh.dayoff.mpmt.acquisitionperiod.Manage.superclass.constructor.call(this, cfg);
    }
